import{_ as t,o as a,c as o,aF as i}from"./chunks/framework.DLvxyDDa.js";const g=JSON.parse('{"title":"service-geokatcher","description":"geoKatcher is a service that allows to monitor geofences between two layers of geospatial data.","frontmatter":{"title":"service-geokatcher","description":"geoKatcher is a service that allows to monitor geofences between two layers of geospatial data."},"headers":[],"relativePath":"packages/service-geokatcher/index.md","filePath":"packages/service-geokatcher/index.md"}'),s={name:"packages/service-geokatcher/index.md"};function r(n,e,d,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="service-geokatcher" tabindex="-1">service-geokatcher <a class="header-anchor" href="#service-geokatcher" aria-label="Permalink to &quot;service-geokatcher&quot;">​</a></h1><p><em>geoKatcher is a service that allows to monitor geofences between two layers of geospatial data.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><strong>geoKatcher</strong> monitors geofences between two layers of geospatial data. For now, only one source is supported:</p><ul><li>Kalisio Maps (<a href="https://github.com/kalisio/kano" target="_blank" rel="noreferrer"><em>Kano</em></a>)</li></ul><p>Using the <a href="https://github.com/feathersjs/feathers" target="_blank" rel="noreferrer">feathers</a> framework and the <a href="https://github.com/kalisio/feathers-distributed" target="_blank" rel="noreferrer">feathers-distributed</a> extension, geoKatcher discovers Kano services and queries them to retrieve layers and features. It also publishes its own <code>monitor</code> service, so other services can interact with it and receive events.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Install with your preferred package manager:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-WTSc2" id="tab-4lz5N0Y" checked><label data-title="pnpm" for="tab-4lz5N0Y">pnpm</label><input type="radio" name="group-WTSc2" id="tab-lfy7AyC"><label data-title="npm" for="tab-lfy7AyC">npm</label><input type="radio" name="group-WTSc2" id="tab-QyeNAR_"><label data-title="yarn" for="tab-QyeNAR_">yarn</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/service-geokatcher</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/service-geokatcher</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/service-geokatcher</span></span></code></pre></div></div></div><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p><strong>service-geokatcher</strong> exposes two HTTP surfaces:</p><ul><li>a <strong><code>/healthcheck</code></strong> endpoint returning the service name and its version;</li><li>a <strong><code>/monitor</code></strong> service providing full CRUD over geofence monitors (<code>POST /monitor</code>, <code>GET /monitor</code>, <code>GET /monitor/:id</code>, <code>PUT /monitor/:id</code>, <code>PATCH /monitor/:id</code>, <code>DELETE /monitor/:id</code>).</li></ul><p>A <strong>monitor</strong> compares two layers — a <code>target</code> and a <code>zone</code> — with an <code>evaluation</code> (<code>geoWithin</code>, <code>geoIntersects</code> or <code>near</code>) and, optionally, runs an <code>action</code> (Slack, crisis or custom webhook) when its alert status changes. Even without an action, the monitor emits an event on its feathers service on every status change. A special <code>dryRun</code> monitor lets you test a configuration without persisting it, running any action or emitting events.</p><p>The full request/response schema — the monitor structure, the evaluation and action options, the service-generated fields and the error codes — is documented on the <a href="./service-geokatcher-openapi.html">API reference</a> page.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The service is configured through environment variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>PORT</code></td><td>The port to expose the service on</td><td><code>8080</code></td></tr><tr><td><code>HOSTNAME</code></td><td>The hostname to expose the service on</td><td><code>localhost</code></td></tr><tr><td><code>DB_URL</code></td><td>The URL of the MongoDB database</td><td><code>mongodb://localhost:27017/geokatcher</code></td></tr><tr><td><code>BASE_URL</code></td><td>The URL used when exposing the service</td><td><code>http://localhost:8080</code></td></tr><tr><td><code>API_PREFIX</code></td><td>The path prefix used to reach the consumed Kano services</td><td><code>/api</code></td></tr><tr><td><code>COTE_ENV</code></td><td>The <a href="https://github.com/kalisio/feathers-distributed" target="_blank" rel="noreferrer">cote</a> environment used to discover Kano — must match the Kano instance</td><td>-</td></tr><tr><td><code>NODE_ENV</code></td><td>Set to <code>development</code> to enable verbose logging</td><td>-</td></tr><tr><td><code>VERSION</code></td><td>Overrides the version reported by <code>/healthcheck</code></td><td>package version</td></tr><tr><td><code>BUILD_NUMBER</code></td><td>When set, added as <code>buildNumber</code> in the <code>/healthcheck</code> response</td><td>-</td></tr></tbody></table><h2 id="running" tabindex="-1">Running <a class="header-anchor" href="#running" aria-label="Permalink to &quot;Running&quot;">​</a></h2><p>Start the service in watch mode for development:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>The service listens on the port set by <code>PORT</code> (default <code>8080</code>), exposing a <code>/healthcheck</code> endpoint. Through <code>feathers-distributed</code>, it waits for a Kano instance&#39;s services to be advertised before it starts querying layers, so a Kano instance reachable on the same <a href="https://github.com/kalisio/feathers-distributed" target="_blank" rel="noreferrer">cote</a> network (same <code>COTE_ENV</code>) must be running for it to become fully operational.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>Run the test suite:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>The <a href="https://vitest.dev/" target="_blank" rel="noreferrer">vitest</a> suite <strong>boots the real service</strong> against a real MongoDB instance and a real Kano instance (started from the workspace scripts, which also set the <code>COTE_ENV</code> the two services need to discover each other over cote) — no mocks are used for the database or for Kano.</p><h2 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h2><p>Build the Docker image (from the package directory):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>This produces <code>service-geokatcher:latest</code> using the monorepo root as the build context. Override the tag with the <code>TAG</code> environment variable.</p><h2 id="deploying" tabindex="-1">Deploying <a class="header-anchor" href="#deploying" aria-label="Permalink to &quot;Deploying&quot;">​</a></h2><p>The image is designed to be deployed with the <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> project.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Licensed under the <a href="https://opensource.org/licenses/MIT" target="_blank" rel="noreferrer">MIT License</a>.</p>',33)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
